### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

#define HASH_SIZE 1000003

typedef struct {
    uint64_t table[HASH_SIZE];
    bool occupied[HASH_SIZE];
} HashSet;

static HashSet set_prefixes;
static HashSet set_suffixes;

static inline void hashset_init(HashSet *hs) {
    memset(hs->occupied, 0, sizeof(hs->occupied));
}

static inline void hashset_insert(HashSet *hs, uint64_t val) {
    uint32_t idx = (uint32_t)(val % HASH_SIZE);
    while (hs->occupied[idx]) {
        if (hs->table[idx] == val) {
            return; // Já inserido
        }
        idx++;
        if (idx == HASH_SIZE) idx = 0;
    }
    hs->occupied[idx] = true;
    hs->table[idx] = val;
}

static inline bool hashset_contains(const HashSet *hs, uint64_t val) {
    uint32_t idx = (uint32_t)(val % HASH_SIZE);
    while (hs->occupied[idx]) {
        if (hs->table[idx] == val) {
            return true;
        }
        idx++;
        if (idx == HASH_SIZE) idx = 0;
    }
    return false;
}

// Codifica a substring str[start ... start + len - 1] em base 27
static inline uint64_t encode(const char *str, int start, int len) {
    uint64_t code = 0;
    for (int i = 0; i < len; i++) {
        code = code * 27 + (uint64_t)(str[start + i] - 'a' + 1);
    }
    return code;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    hashset_init(&set_prefixes);
    hashset_init(&set_suffixes);

    char s[16];

    for (int k = 1; k <= n; k++) {
        if (scanf("%s", s) != 1) break;

        // Se k > 1, checar se S_k pode ser formado pela concatenação de
        // um sufixo de S_a (tamanho L) e um prefixo de S_b (tamanho 10 - L)
        if (k > 1) {
            bool invalid = false;
            for (int L = 1; L <= 10; L++) {
                uint64_t pref_k = encode(s, 0, L);

                // O prefixo de tamanho L de S_k deve ser sufixo de algum S_a anterior
                if (hashset_contains(&set_suffixes, pref_k)) {
                    int rem = 10 - L;
                    if (rem == 0) {
                        invalid = true;
                        break;
                    } else {
                        uint64_t suff_k = encode(s, L, rem);
                        // O restante deve ser prefixo de algum S_b anterior
                        if (hashset_contains(&set_prefixes, suff_k)) {
                            invalid = true;
                            break;
                        }
                    }
                }
            }

            if (invalid) {
                printf("%s\n", s);
                return 0;
            }
        }

        // Adiciona todos os prefixos de S_k
        for (int len = 1; len <= 10; len++) {
            uint64_t pref = encode(s, 0, len);
            hashset_insert(&set_prefixes, pref);
        }

        // Adiciona todos os sufixos de S_k
        for (int len = 1; len <= 10; len++) {
            uint64_t suff = encode(s, 10 - len, len);
            hashset_insert(&set_suffixes, suff);
        }
    }

    printf("ok\n");
    return 0;
}
```

